style.css:
@-moz-document url-prefix("https://www.google.com/"), url-prefix("https://www.google.co.in/") {
img#hplogo,
  img[alt="Google"],
  a[aria-label="Google"] img,
  #hplogo,
  .lnXdpd,
  div[aria-label="Google"] {
    display: none !important;
    background-image: none !important;
  }

  #lga::before,
  #hplogo::before,
  div[aria-label="Google"]::before {
    content: "GAURANSH";
    font-family: "Product Sans", Arial, sans-serif;
    font-weight: 700;
    font-size: 72px;
    letter-spacing: -1px;
    display: inline-block;
    margin-top: 18px;
    color: transparent !important;
    -webkit-background-clip: text;
            background-clip: text;
    background: linear-gradient(90deg,#4285F4 0%,#DB4437 33%,#F4B400 66%,#0F9D58 100%) !important;
  }

  @media (max-width: 600px) {
    #lga::before, #hplogo::before {
      font-size: 38px;
      margin-top: 8px;
    }
  }
}
